function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Process each user-items-list block (each corresponds to a section)
  $('.user-items-list').each(function () {
    const $list = $(this);
    let section = null;

    // Try to get section title from the data-current-context attribute
    const ctxAttr = $list.attr('data-current-context');
    if (ctxAttr) {
      try {
        const ctxObj = JSON.parse(ctxAttr);
        if (ctxObj && ctxObj.sectionTitle) {
          section = cleanText(ctxObj.sectionTitle);
        }
      } catch (_) { /* ignore */ }
    }
    // Fallback to the visible heading inside .list-section-title
    if (!section) {
      const $titleEl = $list.closest('.content-wrapper').find('.list-section-title strong');
      if ($titleEl.length) {
        section = cleanText($titleEl.text());
      }
    }

    // Iterate over each menu item
    $list.find('li.list-item').each(function () {
      const $item = $(this);

      // Dish name (title)
      const $titleEl = $item.find('.list-item-content__title');
      if (!$titleEl.length) return;
      let name = cleanText($titleEl.text());
      if (!name) return;

      // Description: all <p> inside the description wrapper that do NOT contain the price <strong>
      const $descWrapper = $item.find('.list-item-content__description');
      let descText = '';
      if ($descWrapper.length) {
        $descWrapper.find('p').each(function () {
          if ($(this).find('strong').length === 0) {
            descText += ' ' + $(this).text();
          }
        });
      }
      const description = descText ? cleanText(descText) : null;

      // Price: look for the <strong> inside the description wrapper
      let price = null;
      const $priceEl = $descWrapper.find('strong');
      if ($priceEl.length) {
        price = parsePrice($priceEl.text());
      }

      // Build dedup key
      const key = (section || '') + '|' + name + '|' + (price != null ? price : '');
      if (seen.has(key)) return;
      seen.add(key);

      items.push({
        section: section || null,
        name,
        description,
        price
      });
    });
  });

  return items;
}
